/// <summary>
/// builder class for multi select lookup on string control
/// Update"getControlValuesFromTable" and "updateTableRecord" methods for new Enum
/// </summary>
Public class METMultiSelectLookupBuilder
{   
}

Method.Source:
/// <summary>
/// Build lookup for enum
/// </summary>
/// <param name="_sender"> Get form control object</param>
/// <param name="_e"> Get form data source args</param>
/// <param name="_formDataSource"> Get form data source</param>
/// <param name="_formStringControl"> Get form string control</param>
/// <param name="_enumNum"> Get form Enum id</param>
public void buildLookup(FormControl _sender, FormControlEventArgs _e, FormDataSource _formDataSource, FormStringControl _formStringControl, EnumId _enumNum)
{
    Args                                args;
    FormRun                             formRun;
    SysLookupMultiSelectValues          delimitedControlValues;
    SysDictEnum                         sysDictEnum = new SysDictEnum(_enumNum);
    FormControlCancelableSuperEventArgs event       = _e as FormControlCancelableSuperEventArgs;
    
    args = new args(formStr(METEnumLookup));
    args.parm(sysDictEnum.name());
    args.caller(_formStringControl);
    formRun = classFactory.formRunClass(args);
    formRun.init();
    _formStringControl.performFormLookup(formRun);
    FormDataSource metMultiSelectBaseEnumTable_ds ;
    metMultiSelectBaseEnumTable_ds = formRun.dataSource();        
    
    delimitedControlValues  = this.getControlValuesFromTable(_formDataSource,_enumNum); //MPJ_27166_BUYPOFSDEnhancements
    
    if(!delimitedControlValues)
    {
        delimitedControlValues      = _formStringControl.text();
    }
    if(!delimitedControlValues)
    {            
        delimitedControlValues = this.getControlValuesFromMETMultiSelectBaseEnumTable(sysDictEnum);
        
    }
    if(delimitedControlValues)
    {            
        int         counter, conLength;
        container controlValues = str2con(delimitedControlValues, METConstants::Semicolon, false);
        conLength   = conLen(controlValues);
        for (counter = 1; counter <= conLength; counter++)
        {
            METMultiSelectBaseEnumTable  metMultiSelectBaseEnumTable;
            select metMultiSelectBaseEnumTable
                where metMultiSelectBaseEnumTable.EnumText == conpeek(controlValues, counter);
            metMultiSelectBaseEnumTable_ds.findValue(fieldNum(metMultiSelectBaseEnumTable,EnumText),conpeek(controlValues, counter));
            metMultiSelectBaseEnumTable_ds.mark(true);
          
        }
    }
    
   
    formRun.wait();
    str store;
    METMultiSelectBaseEnumTable metMultiSelectBaseEnumTable;
    for (metMultiSelectBaseEnumTable = metMultiSelectBaseEnumTable_ds.getFirst(true) ? metMultiSelectBaseEnumTable_ds.getFirst(true) : metMultiSelectBaseEnumTable_ds.cursor();metMultiSelectBaseEnumTable;
    metMultiSelectBaseEnumTable = metMultiSelectBaseEnumTable_ds.getNext())
    {
        
        store += metMultiSelectBaseEnumTable.EnumText+METConstants::Semicolon;
           
    }
    store = subStr(store,1,strLen(store)-1);
    container controlValues = str2con(delimitedControlValues, METConstants::Semicolon, false);
    controlValues = str2con(store, METConstants::Semicolon, false);            
    this.updateTableRecord(_formDataSource,store,_enumNum); //MPJ_27166_BUYPOFSDEnhancements
   
    event.CancelSuperCall();
}

    /// <summary>
    /// Get Control values from table
    /// </summary>    
    /// <param name="_formDataSource"> Get form data source</param>
    /// <param name="_enumNum"> Get enum id</param>
    /// <returns> A SysLookupMultiSelectValues </returns>
    private SysLookupMultiSelectValues getControlValuesFromTable(FormDataSource _formDataSource, EnumId _enumNum) //MPJ_27166_BUYPOFSDEnhancements
    {
        SysLookupMultiSelectValues delimitedControlValues;
        switch(_formDataSource.table())
        {
            case tableNum(METPurchTable):
                METPurchTable   metPurchTable;
                metPurchTable           = _formDataSource.cursor();
                //MPJ_27166_BUYPOFSDEnhancements
                switch(_enumNum)
                {
                    case enumNum(METPOSubMode):
                        delimitedControlValues  = metPurchTable.POSubMode;
                        break;
                    
                    case enumNum(METPOChngSubMode):
                        delimitedControlValues  = metPurchTable.POChngSubMode;
                        break;
                }
                //MPJ_27166_BUYPOFSDEnhancements
                break;
            //MPJ_21178_VendorGlobal
            case tableNum(METVendTable):
                METVendTable   metVendTable;
                metVendTable            = _formDataSource.cursor();
                delimitedControlValues  = metVendTable.VendDistributionMethod;
                break;

        }
        return delimitedControlValues;
    }

/// <summary>
/// Get Control values from METMultiSelectBaseEnumTable
/// </summary>    
/// <param name="_sysDictEnum"> Get form Enum id</param>
/// <returns> A SysLookupMultiSelectValues </returns>
private SysLookupMultiSelectValues getControlValuesFromMETMultiSelectBaseEnumTable(SysDictEnum _sysDictEnum)
{
    METMultiSelectBaseEnumTable metMultiSelectBaseEnumTableValues;
    SysLookupMultiSelectValues  delimitedControlValues;
    while select EnumText from  metMultiSelectBaseEnumTableValues
            where metMultiSelectBaseEnumTableValues.EnumName == _sysDictEnum.name()
    {
        delimitedControlValues += metMultiSelectBaseEnumTableValues.EnumText+METConstants::Semicolon;
    }
    return delimitedControlValues;
}

    /// <summary>
    /// update record with selected values
    /// </summary>
    /// <param name="_formDataSource"> Get form data source</param>
    /// <param name="_Store"> Get selected values</param>
    private void updateTableRecord(FormDataSource _formDataSource, str _Store,EnumId _enumNum) //MPJ_27166_BUYPOFSDEnhancements
    {       
        switch(_formDataSource.table())
        {
            case tableNum(METPurchTable):
                METPurchTable   metPurchTable;
                metPurchTable           = _formDataSource.cursor();                
                //MPJ_27166_BUYPOFSDEnhancements
                switch(_enumNum)
                {
                    case enumNum(METPOSubMode):
                        metPurchTable.POSubMode=_Store;
                        break;
                    
                    case enumNum(METPOChngSubMode):
                        metPurchTable.POChngSubMode=_Store;
                        break;
                }
                //MPJ_27166_BUYPOFSDEnhancements
                

                metPurchTable.write();
                _formDataSource.reread();
                break;
            //MPJ_21178_VendorGlobal
            case tableNum(METVendTable):
                METVendTable   metVendTable;
                metVendTable           = _formDataSource.cursor();
                metVendTable.VendDistributionMethod=_Store;
                metVendTable.write();
                _formDataSource.reread();
                break;
        }
        
    }
